import { FlatList, Pressable, Text, View, type ViewProps } from "react-native";
import { Button } from "@/components/nyc-tron/ui/components/Button";
import { ErrorMessage } from "@/components/nyc-tron/ui/components/feedback/ErrorMessage";
import { joinClasses } from "@/components/nyc-tron/ui/components/styles";
import { validateHistory, type HistoryEntry, type HistoryJump } from "@/components/nyc-tron/ui/components/shell/history-model";
import { useOwnedAction } from "@/components/nyc-tron/ui/components/shell/useOwnedAction";
import { space } from "@/components/nyc-tron/ui/tokens";
export type { HistoryEntry, HistoryJump } from "@/components/nyc-tron/ui/components/shell/history-model";

export interface HistoryPanelProps extends Omit<ViewProps, "children"> {
  readonly documentId: string;
  readonly revision: string;
  readonly entries: readonly HistoryEntry[];
  readonly cursor: number;
  readonly onJump: (request: HistoryJump, signal: AbortSignal) => void | Promise<void>;
  readonly label?: string;
  readonly height?: number;
  readonly className?: string;
  readonly unstyled?: boolean;
}

/** Controlled history. The host applies the jump atomically and supplies the new cursor. */
export function HistoryPanel({ documentId, revision, entries, cursor, onJump, label = "History", height = 320, className, unstyled = false, style, ...rest }: HistoryPanelProps) {
  validateHistory(entries, cursor);
  if (!Number.isFinite(height) || height < 44) throw new RangeError("History height must be at least 44");
  const action = useOwnedAction(JSON.stringify([documentId, revision]));
  const pending = action.pending !== null;
  const jump = (target: number) => {
    if (pending || target === cursor) return;
    void action.run(String(target), signal => onJump({ documentId, expectedRevision: revision, cursor: target }, signal));
  };
  const styled = !unstyled;
  return <View {...rest} style={[{ gap: space[2] }, style]} {...{ className: joinClasses(className) }}>
    <Text accessibilityRole="header" {...{ className: joinClasses(styled && "text-text font-semibold") }}>{label}</Text>
    <Text accessibilityLiveRegion="polite" {...{ className: joinClasses(styled && "text-text-muted") }}>{pending ? "Restoring history…" : `State ${cursor} of ${entries.length}`}</Text>
    <View style={{ flexDirection: "row", flexWrap: "wrap", gap: space[2] }}>
      <Button title="Undo" disabled={pending || cursor === 0} onPress={() => jump(cursor - 1)} unstyled={unstyled}/>
      <Button title="Redo" disabled={pending || cursor === entries.length} onPress={() => jump(cursor + 1)} unstyled={unstyled}/>
      {pending ? <Button title="Cancel history request" onPress={action.cancel} unstyled={unstyled}/> : null}
    </View>
    <Button title="Initial state" accessibilityLabel={cursor === 0 ? "Current state: Initial state" : "Restore initial state"} disabled={pending || cursor === 0} onPress={() => jump(0)} unstyled={unstyled}/>
    <FlatList data={entries} keyExtractor={entry => entry.id} style={{ height }} initialNumToRender={12} windowSize={5}
      accessibilityLabel={label} ListEmptyComponent={<Text {...{ className: joinClasses(styled && "text-text-muted") }}>No document edits</Text>}
      renderItem={({ item, index }) => <Pressable accessibilityRole="button" accessibilityLabel={`${cursor === index + 1 ? "Current state" : "Restore state"} ${index + 1}: ${item.label}`}
        accessibilityState={{ disabled: pending }} {...(cursor === index + 1 ? { "aria-current": "step" as const } : {})}
        disabled={pending} onPress={() => jump(index + 1)}
        {...{ className: joinClasses(styled && "border-b border-border focus-visible:ring-2 focus-visible:ring-focus") }}
        style={{ minHeight: 56, padding: space[2.5], gap: space[1] }}>
        <Text {...{ className: joinClasses(styled && (index < cursor ? "text-text" : "text-text-muted")) }}>{item.label}</Text>
        {item.detail ? <Text {...{ className: joinClasses(styled && "text-text-muted text-sm") }}>{item.detail}</Text> : null}
        {item.timestampMs !== undefined ? <Text {...{ className: joinClasses(styled && "text-text-muted text-sm") }}>{new Date(item.timestampMs).toLocaleString()}</Text> : null}
      </Pressable>}/>
    <ErrorMessage {...(action.error ? { message: action.error } : {})} unstyled={unstyled}/>
  </View>;
}

import { createStore } from "zustand/vanilla";

/** UI request state. Abort controllers stay in the owner's closure. */
export interface ActionState { readonly pending: string | null; readonly error: string | null }
export function createActionOwner(currentScope: () => string) {
  const store = createStore<ActionState>(() => ({ pending: null, error: null }));
  let active = false;
  let current: { readonly scope: string; readonly abort: AbortController } | null = null;
  function cancel() {
    const previous = current; current = null;
    previous?.abort.abort();
  }
  return {
    store,
    activate() { cancel(); active = true; store.setState({ pending: null, error: null }); },
    deactivate() { active = false; cancel(); },
    cancel() { cancel(); store.setState({ pending: null }); },
    async run<T>(id: string, operation: (signal: AbortSignal) => T | Promise<T>, consume?: (value: T) => void, options?: { pendingForAsyncOnly?: boolean }): Promise<boolean> {
      if (!active) return false;
      cancel();
      const request = { scope: currentScope(), abort: new AbortController() };
      current = request;
      const valid = () => active && current === request && request.scope === currentScope();
      if (options?.pendingForAsyncOnly) store.setState({ error: null });
      else store.setState({ pending: id, error: null });
      try {
        if (!valid()) return false;
        const result = operation(request.abort.signal);
        let value: T;
        if (options?.pendingForAsyncOnly) {
          if (result && typeof (result as Promise<T>).then === 'function') {
            // A synchronous acknowledgement or already-resolved promise must not
            // disable (and blur) the focused control between keyboard commands.
            let settled = false;
            const completion = Promise.resolve(result).then(value => { settled = true; return value; }, error => { settled = true; throw error; });
            void Promise.resolve().then(() => { if (!settled && valid()) store.setState({ pending: id, error: null }); });
            value = await completion;
          } else value = result as T;
        } else value = await result;
        if (!valid()) return false;
        consume?.(value);
        if (!valid()) return false;
        store.setState({ pending: null });
        return true;
      } catch (error) {
        if (!valid()) return false;
        store.setState({ pending: null, error: error instanceof Error ? error.message : String(error) });
        return false;
      } finally { if (current === request) current = null; }
    },
  };
}

import { useLayoutEffect, useRef } from "react";
import { useStore } from "zustand";
import { createActionOwner } from "@/components/nyc-tron/ui/components/shell/action-owner";

/** Cancel stale requests at the committed document boundary, before new controls accept input. */
export function useOwnedAction(scope: string) {
  const committed = useRef(scope);
  const ref = useRef<ReturnType<typeof createActionOwner> | null>(null);
  ref.current ??= createActionOwner(() => committed.current);
  const owner = ref.current;
  useLayoutEffect(() => {
    committed.current = scope;
    owner.activate();
    return () => owner.deactivate();
  }, [owner, scope]);
  const state = useStore(owner.store, value => value);
  const run: typeof owner.run = (id, operation, consume, options) => committed.current === scope ? owner.run(id, operation, consume, options) : Promise.resolve(false);
  return { ...state, run, cancel: owner.cancel };
}

/**
 * Tailwind classes are merged at the APP boundary. Joining without
 * tailwind-merge avoids deleting custom typography/color utilities that
 * depend on each consumer's own @theme configuration.
 */
export function joinClasses(...items: Array<string|false|null|undefined>):string {
  return items.filter(Boolean).join(" ");
}

